Here is the equivalent Go code using the AWS SDK:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/cognitoidentityprovider"
)

func main() {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("us-east-2")}, nil)
	if err != nil {
		log.Fatal(err)
	}

	cognitoIDP := cognitoidentityprovider.New(sess)

	params := &cognitoidentityprovider.ListUsersInGroupInput{
		UserPoolId: aws.String("us-east-2_4YtYz6hV0"),
		GroupName:  aws.String("account:6412003a7a61c0beecdd16a7"),
	}

	result, err := cognitoIDP.ListUsersInGroup(context.Background(), params)
	if err != nil {
		log.Fatal(err)
	}

	var users []string
	for _, user := range result.Users {
		for _, attribute := range user.Attributes {
			if *attribute.Name == "custom:profileType" {
				if *attribute.Value == "1" || *attribute.Value == "2" {
					users = append(users, *user.Username)
				}
			}
		}
	}

	for _, user := range users {
		fmt.Println(user)
	}
}
```
Note that you'll need to install the AWS SDK for Go using `go get github.com/aws/aws-sdk-go` and import the necessary packages.

Also, make sure to replace the `us-east-2_4YtYz6hV0` and `account:6412003a7a61c0beecdd16a7` placeholders with your actual Cognito User Pool ID and Group Name.

